typedef float rational_t;

class singleton
{
protected:
  singleton() {}
  virtual ~singleton() {}
};

class matrix4x4
{
public:
  float m[4][4];
};

class vector3d
{
public:
  float x, y, z;
  vector3d() {}
  vector3d(rational_t _x, rational_t _y, rational_t _z) : x(_x), y(_y), z(_z) {}
};

class hull;

void *os_malloc32(int size);
extern const matrix4x4 identity_matrix;

class geometry_manager : public singleton
{
public:
  enum xform_t
  {
    XFORM_LOCAL_TO_WORLD, XFORM_WORLD_TO_VIEW, XFORM_VIEW_TO_WORLD,
    XFORM_VIEW_TO_PROJECTION, XFORM_PROJECTION_TO_SCREEN,
    XFORM_EFFECTIVE_WORLD_TO_VIEW, XFORM_VIEW_TO_SCREEN,
    XFORM_WORLD_TO_PROJECTION, XFORM_WORLD_TO_SCREEN, NUM_XFORMS
  };

  geometry_manager();
  virtual ~geometry_manager();

  matrix4x4 *xforms;
  vector3d camera_pos;
  vector3d camera_up;
  vector3d camera_dir;
  matrix4x4 scene_analyzer;
  bool scene_analyzer_enabled;
};

geometry_manager::geometry_manager()
{
  xforms = (matrix4x4*)os_malloc32(NUM_XFORMS*sizeof(matrix4x4));
  for (int i=NUM_XFORMS; --i>=0; )
    xforms[i]=identity_matrix;

  scene_analyzer_enabled=false;
  scene_analyzer=identity_matrix;

  camera_pos = vector3d(0,0,0);
  camera_up  = vector3d(0,1,0);
  camera_dir = vector3d(0,0,1);
}
